#!/usr/bin/env python3
"""Embed the unchanged, user-supplied JP1 reference image in firmware."""
import argparse
import hashlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "src/web_assets/jp1-pinout.jpg"
HEADER = ROOT / "src/panel_web_pinout.h"


def render(data):
    digest = hashlib.sha256(data).hexdigest()
    rows = ["  " + ", ".join(f"0x{value:02x}" for value in data[pos:pos + 16]) + ","
            for pos in range(0, len(data), 16)]
    return ("#pragma once\n"
            "// Generated by scripts/embed_pinout.py; do not edit the byte array.\n"
            "// User-supplied reference image, preserved without conversion.\n"
            "// Source: src/web_assets/jp1-pinout.jpg\n"
            f"// SHA-256: {digest}\n"
            "#include <stdint.h>\n\n"
            "static const uint8_t kJp1PinoutJpeg[] PROGMEM = {\n"
            + "\n".join(rows) + "\n};\n")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="verify the existing header without writing")
    args = parser.parse_args()
    data = SOURCE.read_bytes()
    if not data.startswith(b"\xff\xd8") or not data.endswith(b"\xff\xd9"):
        parser.error("Source is not a complete JPEG")
    expected = render(data)
    if args.check:
        if not HEADER.exists() or HEADER.read_text(encoding="ascii") != expected:
            parser.error("Embedded header differs from the source image; run scripts/embed_pinout.py")
        print(f"PASS: embedded JP1 image matches {len(data)} source bytes; SHA-256 {hashlib.sha256(data).hexdigest()}")
    else:
        HEADER.write_text(expected, encoding="ascii", newline="\n")
        print(f"Embedded {len(data)} unchanged JPEG bytes in {HEADER.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
